27	const PROCESSING_FEE = 5;
28	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	// Kept as an exact fraction rather than `amount * 1.1`, which drifts in
38	// floating point (100 * 1.1 === 110.00000000000001).
39	const withFirstInsuranceSurcharge = (amount: number): number =>
40	  (amount * 11) / 10;
41	
42	const BLOCK_SIZE = 3;
43	const BLOCK_BASE_PREMIUM = 60;
44	
45	const countByType = (items: Item[]): Map<string, number> => {
46	  const counts = new Map<string, number>();
47	  for (const item of items) {
48	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
49	  }
50	  return counts;
51	};
52	
53	const policyBasePremiumOf = (items: Item[]): number => {
54	  let total = 0;
55	  for (const [type, count] of countByType(items)) {
56	    total +=
57	      count === BLOCK_SIZE
58	        ? BLOCK_BASE_PREMIUM
59	        : count * BASE_PREMIUM_BY_TYPE[type];
60	  }
61	  return total;
62	};
63	
64	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
65	  const results = scenario.steps.map((step) => {
66	    const policyBasePremium = policyBasePremiumOf(step.items);
67	    const premium =
68	      withFirstInsuranceSurcharge(policyBasePremium) + PROCESSING_FEE;
69	    return { premium };
70	  });
71	
72	  return { results };
73	};
