// A group of exactly BLOCK_SIZE alike items forms a block and is charged a
// flat BLOCK_BASE_PREMIUM instead of the per-item price list rate.
const basePremiumForAlikeItems = (type: string, count: number): number =>
  count === BLOCK_SIZE
    ? BLOCK_BASE_PREMIUM
    : count * BASE_PREMIUM_BY_TYPE[type];

const policyBasePremiumOf = (items: Item[]): number =>
  [...countByType(items)].reduce(
    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
    0,
  );
